function makeSvgAvatar(bg1, bg2, iconPath, accent = "#d8ac5c") {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 240">
    <defs>
      <linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="${bg1}"/>
        <stop offset="100%" stop-color="${bg2}"/>
      </linearGradient>
    </defs>
    <rect width="160" height="240" fill="url(#g)"/>
    <rect x="8" y="8" width="144" height="224" rx="6" fill="none" stroke="${accent}" stroke-width="2" stroke-opacity="0.45"/>
    <circle cx="80" cy="86" r="32" fill="${accent}" fill-opacity="0.2" stroke="${accent}" stroke-width="2"/>
    <path d="M28 215 C28 158 132 158 132 215 Z" fill="${accent}" fill-opacity="0.18" stroke="${accent}" stroke-width="2"/>
    <g transform="translate(56, 62)" fill="${accent}">${iconPath}</g>
  </svg>`;
  return "data:image/svg+xml;utf8," + encodeURIComponent(svg);
}

